steps.solution:
#include <iostream>
#include <string>
using namespace std;

int main() {
    string target;
    int distance;
    int speed;

    getline(cin, target);
    cin >> distance >> speed;

    int time = distance / speed;

    cout << "TARGET: " << target << endl;
    cout << "TIME: " << time << " H" << endl;
    return 0;
}
